#include "anl93.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
uint32_t anl93_crc32(const void *data,size_t n){const uint8_t*p=data;uint32_t c=~0u;for(size_t i=0;i<n;++i){c^=p[i];for(int b=0;b<8;++b)c=(c&1u)?(c>>1)^0xedb88320u:c>>1;}return~c;}
int main(int argc,char**argv){if(argc!=2){printf("ANLCHECK 0.9.3\nUsage: %s <archive>\n",argv[0]);return 1;}FILE*f=fopen(argv[1],"rb");ANL93Header h;if(!f||fread(&h,sizeof h,1,f)!=1){if(f)fclose(f);return 1;}uint32_t got=h.header_crc32;h.header_crc32=0;if(memcmp(h.magic,ANL93_MAGIC,4)||h.version!=ANL93_VERSION||h.block_size!=ANL93_BLOCK_SIZE||anl93_crc32(&h,sizeof h)!=got||h.record_count!=h.block_count){fclose(f);fputs("STATUS: INVALID HEADER\n",stderr);return 1;}uint32_t raw=0,br=0,mb=0;for(uint32_t i=0;i<h.block_count;++i){ANL93Record r;if(fread(&r,sizeof r,1,f)!=1||r.block_index!=i||r.header_size!=sizeof r||r.payload_size>h.block_size){fclose(f);fputs("STATUS: INVALID RECORD\n",stderr);return 1;}uint8_t*p=r.payload_size?malloc(r.payload_size):NULL;if(r.payload_size&&(!p||fread(p,1,r.payload_size,f)!=r.payload_size||anl93_crc32(p,r.payload_size)!=r.crc32)){free(p);fclose(f);fputs("STATUS: INVALID PAYLOAD\n",stderr);return 1;}if(r.type==ANL93_RAW)++raw;else if(r.type==ANL93_BLOCK_REF&&r.payload_size==4)++br;else if(r.type==ANL93_MINIBLOCK&&r.payload_size>=sizeof(ANL93MiniHeader))++mb;else{free(p);fclose(f);fputs("STATUS: INVALID TYPE\n",stderr);return 1;}free(p);}if(fgetc(f)!=EOF){fclose(f);fputs("STATUS: TRAILING DATA\n",stderr);return 1;}fclose(f);printf("# ANLCHECK 0.9.3\nBlocks: %u\nRAW: %u\nBlock references: %u\nMiniBlocks: %u\nHeader CRC: OK\nSTATUS: ANL9 0.9.3 ARCHIVE STRUCTURALLY VALID\n",h.block_count,raw,br,mb);return 0;}
